# Construct the 30x30 repeated tile field, then add matching-color connectors in inter-tile gaps.
colors = [[3,2,2,3],[2,8,8,2],[3,2,2,3],[2,8,8,2]]
g = [[0]*30 for _ in range(30)]
for r0 in range(5):
  for c0 in range(5):
    ro, co = 1+7*r0, 1+7*c0
    for dr in range(5):
      rr=ro+dr
      if rr>=30: continue
      for dc in range(5):
        cc=co+dc
        if cc>=30: continue
        if dr in (0,4) or dc in (0,4):
          g[rr][cc]=4
        elif r0<4 and c0<4:
          g[rr][cc]=colors[r0][c0]
# Fill horizontal blank separators between any two equal-color markers in a tile row.
for r in range(4):
  for c1 in range(4):
    for c2 in range(c1+1,4):
      if colors[r][c1] == colors[r][c2]:
        val=colors[r][c1]
        for c in range(c1,c2):
          for cc in range(1+7*c+5, 1+7*(c+1)):
            for dr in (1,2,3): g[1+7*r+dr][cc]=val
# Fill vertical blank separators between any two equal-color markers in a tile column.
for c in range(4):
  for r1 in range(4):
    for r2 in range(r1+1,4):
      if colors[r1][c] == colors[r2][c]:
        val=colors[r1][c]
        for r in range(r1,r2):
          for rr in range(1+7*r+5, 1+7*(r+1)):
            for dc in (1,2,3): g[rr][1+7*c+dc]=val
print('\n'.join('['+', '.join(map(str,row))+'],' for row in g))

